solution.solution.cpp:
int number{ 5 };
int& alias{ number };
const int limit{ 100 };

auto& a{ alias };
const auto b{ limit };
const auto& c{ limit };

unitTests:
static_assert(std::is_same_v<decltype(a), int&>, "a should be declared with auto&");
static_assert(std::is_same_v<decltype(b), const int>, "b should be declared with const auto");
static_assert(std::is_same_v<decltype(c), const int&>, "c should be declared with const auto&");

TEST("a really is another name for number") { a = 42; CHECK_EQ(number, 42); }
TEST("b and c hold the limit") { CHECK_EQ(b, 100); CHECK_EQ(c, 100); CHECK(&c == &limit); }

